import{_t as e,it as t,n,rt as r}from"./chunks/framework.BJB2RXm-.js";var i=JSON.parse(`{"title":"CI/CD","description":"","frontmatter":{},"headers":[],"relativePath":"ci-cd.md","filePath":"ci-cd.md"}`),a={name:`ci-cd.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="ci-cd" tabindex="-1">CI/CD <a class="header-anchor" href="#ci-cd" aria-label="Permalink to “CI/CD”">​</a></h1><p>GitHub Actions manages pull request validation, testing, releases, documentation deployment, and release cleanup.</p><h2 id="pull-request-checks" tabindex="-1">Pull request checks <a class="header-anchor" href="#pull-request-checks" aria-label="Permalink to “Pull request checks”">​</a></h2><p><code>pr.yml</code> runs the main CI checks for pull requests and pushes to <code>main</code>. It coordinates the reusable quality, unit, integration, Playwright, and SonarQube workflows.</p><p>For pull requests, Nx limits applicable tests to affected projects. Pushes to <code>main</code> run the applicable test targets across all projects.</p><h3 id="quality-checks" tabindex="-1">Quality checks <a class="header-anchor" href="#quality-checks" aria-label="Permalink to “Quality checks”">​</a></h3><p><code>pr-quality.yml</code>:</p><ul><li>Applies labels based on changed files.</li><li>Runs PHP, JavaScript, CSS, Markdown, <code>package.json</code>, and template-part linting.</li></ul><h3 id="unit-tests" tabindex="-1">Unit tests <a class="header-anchor" href="#unit-tests" aria-label="Permalink to “Unit tests”">​</a></h3><p><code>pr-unit.yml</code> runs JavaScript unit tests.</p><p>Pull requests test affected projects. Pushes to <code>main</code> run the target across all applicable projects.</p><h3 id="integration-tests" tabindex="-1">Integration tests <a class="header-anchor" href="#integration-tests" aria-label="Permalink to “Integration tests”">​</a></h3><p><code>pr-integration.yml</code> runs PHP integration tests.</p><p>Pull requests test affected projects. Pushes to <code>main</code> run the target across all applicable projects.</p><p>PHP coverage is collected when available and passed to SonarQube.</p><h3 id="playwright-tests" tabindex="-1">Playwright tests <a class="header-anchor" href="#playwright-tests" aria-label="Permalink to “Playwright tests”">​</a></h3><p><code>pr-playwright.yml</code> runs Playwright tests for projects that provide e2e, accessibility, or screenshot test targets.</p><p>Pull requests test affected projects. Pushes to <code>main</code> test all applicable projects.</p><p>Each project runs separately. Failed Playwright runs upload test results, including available screenshot differences and traces.</p><h3 id="sonarqube" tabindex="-1">SonarQube <a class="header-anchor" href="#sonarqube" aria-label="Permalink to “SonarQube”">​</a></h3><p><code>pr-sonarqube.yml</code> runs the SonarQube scan after integration tests and includes PHP coverage when available.</p><h2 id="pull-request-titles" tabindex="-1">Pull request titles <a class="header-anchor" href="#pull-request-titles" aria-label="Permalink to “Pull request titles”">​</a></h2><p><code>pr-title.yml</code> validates pull request titles against the repository&#39;s supported Conventional Commit types:</p><ul><li><code>feat</code></li><li><code>fix</code></li><li><code>perf</code></li><li><code>revert</code></li><li><code>docs</code></li><li><code>style</code></li><li><code>refactor</code></li><li><code>test</code></li><li><code>build</code></li><li><code>ci</code></li><li><code>chore</code></li></ul><p>The scope is optional.</p><h2 id="screenshot-generation" tabindex="-1">Screenshot generation <a class="header-anchor" href="#screenshot-generation" aria-label="Permalink to “Screenshot generation”">​</a></h2><p><code>screenshot.yml</code> is a manually triggered workflow for regenerating screenshot baselines for a selected project.</p><p>It:</p><ol><li>Runs the project&#39;s <code>test-screenshot-generate</code> target.</li><li>Commits changed snapshots.</li><li>Pushes the changes back to the current branch.</li></ol><p>The workflow does not run against <code>main</code>.</p><h2 id="releases" tabindex="-1">Releases <a class="header-anchor" href="#releases" aria-label="Permalink to “Releases”">​</a></h2><p><code>tag.yml</code> is the manual release workflow for WordPress plugins and themes.</p><p>The maintainer selects:</p><ul><li>the project</li><li>whether the release is an alpha</li><li>an optional version</li></ul><p>If no version is supplied, Nx determines the release version.</p><p>The workflow:</p><ol><li>Runs Nx Release for the selected project.</li><li>Creates the release tag and GitHub Release.</li><li>Builds the release archive.</li><li>Uploads the ZIP to the GitHub Release.</li><li>Updates the Composer <code>packages.json</code>.</li><li>Publishes the updated Composer repository to GitHub Pages.</li></ol><p>Release tags use the project name and version:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;nx-project-name&gt;/v&lt;semver&gt;</span></span></code></pre></div><p>Release operations use a GitHub App token so the workflow can commit and create tags where repository protection requires it.</p><h2 id="deleted-releases" tabindex="-1">Deleted releases <a class="header-anchor" href="#deleted-releases" aria-label="Permalink to “Deleted releases”">​</a></h2><p><code>tag-delete.yml</code> runs when a Git tag is deleted.</p><p>For supported release tags, it removes the corresponding release metadata from <code>packages.json</code> and republishes the Composer repository to GitHub Pages.</p><p>Release creation and deletion share a concurrency group so they cannot update <code>packages.json</code> at the same time.</p><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to “Documentation”">​</a></h2><p><code>deploy-docs.yml</code> builds the VitePress documentation site when relevant documentation or documentation-build files change.</p><p>Pull requests build the documentation without deploying it.</p><p>Changes on <code>main</code> and manually triggered runs publish the generated site to the <code>docs</code> directory on GitHub Pages.</p><h2 id="shared-workflow-setup" tabindex="-1">Shared workflow setup <a class="header-anchor" href="#shared-workflow-setup" aria-label="Permalink to “Shared workflow setup”">​</a></h2><p><code>.github/actions/setup/action.yml</code> provides common dependency setup for workflows.</p><p>It:</p><ul><li>Configures Node.js 24.</li><li>Configures pnpm 10 and installs dependencies from the lockfile.</li><li>Optionally installs Composer dependencies with caching.</li></ul><p>Individual workflows enable Composer setup only when required.</p><h2 id="dependency-updates" tabindex="-1">Dependency updates <a class="header-anchor" href="#dependency-updates" aria-label="Permalink to “Dependency updates”">​</a></h2><p>Dependabot manages dependency update pull requests:</p><ul><li>npm dependencies are checked daily.</li><li>Composer dependencies are checked weekly.</li><li>Updates are assigned to the <code>bcgov/digital-engagement-solutions-custom-web</code> team for review.</li></ul><p>Dependabot limits each package ecosystem to three open pull requests.</p><h2 id="pull-request-labels" tabindex="-1">Pull request labels <a class="header-anchor" href="#pull-request-labels" aria-label="Permalink to “Pull request labels”">​</a></h2><p><code>.github/labeler.yml</code> automatically labels pull requests based on changed paths.</p><p>Labels identify:</p><ul><li>monorepo-level changes</li><li>plugin changes</li><li>theme changes</li><li>specific plugins and themes</li></ul>`,61)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};